#pragma once

#include <optional>
#include <QVector2D>

inline std::optional<int> barNumberForBeat(int beatIndex) {
    if (beatIndex < 0 || beatIndex % 4 != 0) {
        return std::nullopt;
    }
    return beatIndex / 4 + 1;
}

inline QVector2D uprightBarLabelVertex(
        QVector2D origin, QVector2D offset, Qt::Orientation orientation) {
    return origin + (orientation == Qt::Vertical
                    ? QVector2D(offset.y(), -offset.x()) : offset);
}
